import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第102章 一个钟头","description":"","frontmatter":{},"headers":[],"relativePath":"第102章_一个钟头.md","filePath":"第102章_一个钟头.md"}'),o={name:"第102章_一个钟头.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第102章-一个钟头" tabindex="-1">第102章 一个钟头 <a class="header-anchor" href="#第102章-一个钟头" aria-label="Permalink to &quot;第102章 一个钟头&quot;">​</a></h1><p>那个周六我们见了一次面，一个钟头。</p><p>那天晚上我们在手机上说了三个钟头四十分钟。</p><p>我把这两个数并排写下来，是因为它太准确了。</p><p>在一张桌子上，我们用一个钟头讲了分装、贴单、错件、钱怎么走。她讲了三次&quot;这个你知道了就往下&quot;。我讲了两次&quot;好&quot;。其他全在单子上。</p><p>那天她带了一个袋子，把单子摊在桌上，用两只手压着边。奶茶店那个桌子很小，她的手肘一压，杯子就往我这边滑。我把杯子推回去，推了两次。</p><p>她说她今天不讲怎么发货，她只讲三件事。第一件，钱怎么走。第二件，出错怎么办。第三件，你别问我为什么找你。</p><p>我说第三件你说。</p><p>她说因为她要是回答了这个，她今天下午回去就要开始想他们两个是什么。</p><p>关于第二件，她讲了九分钟。哪一天之前客人可以退，哪一天之后退件算她的，丢件怎么平分，哪一家快递不赔。她讲得极清楚，清楚到我拿笔在一张纸上写了五行。</p><p>我写的时候她看着我。</p><p>她说你真的写。</p><p>我说我习惯。</p><p>她说你写下来你就不会错，你不会错，我这边出了错就是我在错，我们两个里必须有一个人会错，我不太愿意那个人是我。</p><p>我说那我今天不记。</p><p>我把那张纸从本子里抽出来，叠了一下，压到桌子底下。</p><p>那个店她选了三次才定下来。后来她告诉我为什么：那家店靠窗一排六个位子，背后没有人。她说她背后有人她讲不出话。</p><p>那天一个钟头里，我一个字也没多说。</p><p>晚上十一点，她上线了。</p><p>她说你今天很累吧。</p><p>我说我不累。</p><p>她说你坐那个椅子的样子很像累。</p><p>我说，我那是不知道手放哪儿。</p><p>她那边没马上回。我把桌上那杯没喝的东西挪开，把本子摊平。我这几年有一个毛病：跟人讲话的时候我手上要有东西，不然我就开始转杯子。</p><p>我说，今天我看见你抬手看了三次表。</p><p>她说，你数了。</p><p>我说，我数了你抬手三次，低头看单子五次，把那杯东西转了两次，看窗外七次。</p><p>她隔了很久。</p><p>她说，闻迟，你今天下午在我对面坐了一个钟头，你干的事是统计我。</p><p>我说我不是统计你。</p><p>她说你就是。她说你这个人你没办法。她说我早就知道你没办法，我今天还是找你。</p><p>我说，那你现在知道更清楚了，你今天晚上还是在这儿跟我讲话。</p><p>她说对。她说这就是问题。</p><p>她把话转到别的地方去了。她说明天要发三十七个件，问我那个袋子够不够。我说够。她说那你去睡。</p><p>我说我没困。</p><p>她说你没困你也不该今天晚上想这个。</p><p>那天夜里十一点五十八，她忽然发回来一段。</p><p>这段不是关于货。</p><p>她说她今天下午走的时候，做了一件事，她一整晚在屋里来回走了四十分钟。</p><p>她说她把那个杯盖放进我包的外袋里了。</p><p>那个杯盖是那年我在雨棚底下见过的那一个，她手上的一半。我们两个一人一半，一人拿了六年。</p><p>她说她进去之前是空手的，出来也是空手的，中间那个东西在我这儿。</p><p>我说，你想拿回去。</p><p>她说她不想拿回去。</p><p>她说她要真想拿，她今天下午就讲了。</p><p>我说那你难受什么。</p><p>她说，因为我做了这件事。</p><p>她说，我这一辈子做了事我不敢认。</p><p>她说她今天下午在我对面坐了六十分钟，一句多余的话不讲，手上做了这一件事。她说她要是现在跟我承认了，她就得承认她今天下午不是来谈钱的。</p><p>我把台灯拧暗了一格。</p><p>我说，你今天别讲这个了。</p><p>她说，你不让我讲，你明天就要开始想我今天为什么只来了一个钟头。</p><p>她说她今天讲这个不是为了让我难受。</p><p>她说她今天要是不讲，她明天早上起来就要把那个杯子拿回来。她说她拿回来我们就又要约一次见面，那一次她就要在门口站着，不敢按门铃。</p><p>她说，我把它给你，是因为我给它找了一个地方。</p><p>我说那我不扔。</p><p>她说你敢扔。</p><p>我说我不扔。</p><p>她说，那你不要放在桌上。</p><p>我问为什么。</p><p>她说，你放在桌上你每天看见，你每天看见你每天晚上就要想，你想多了你就要来找我讲。</p><p>她说，你把它放进你那个抽屉。</p><p>我问为什么是抽屉。</p><p>她说，因为你的抽屉你不会天天开。</p><p>那天夜里我去看了那个抽屉。</p><p>我桌上那个塑料杯盖还在原来的位置。我把它拿起来，用一张纸包住，因为它是塑料的，塑料碰上铁会响。我不想每天早上被一个杯盖响醒。</p><p>我把它推回抽屉最里面。</p><p>第二天早上我七点起，拿东西的时候那个纸包还在。我没打开。</p><p>我那天上午发了十九个件。</p><p>月末陈树来我屋里拿螺丝刀。</p><p>他拉开我抽屉找东西，看见了那个纸包。</p><p>他把抽屉推回去一半，又拉开。</p><p>他说你这里放着一个别人落的东西，你是不是天天看。</p><p>我说我不开抽屉我就不看。</p><p>他说他去年来的话，这个抽屉里全是数据线，今年里面有一个不属于我的东西。</p><p>我说我就是放这儿。</p><p>他把螺丝刀拿走，走到门口停了一下。</p><p>他说，你这个人存东西，你存的都是不能讲的事。他说你存一次，你就多一个不能讲。他说你存到你三十岁，你这屋子里全是你不能讲话的人。</p><p>那天晚上我把那个纸包拿出来过一次。</p><p>纸的边已经被抽屉里别的东西磨毛了。</p><p>我没拆。</p><p>我又放回去了。</p><p>我放回去那一下我想明白了他那句话。</p><p>我这四年存下来的东西，垒在一起，全部是为了不要开口。</p><p>我在那个抽屉里放了六年。六年以后我还留着那个纸包。纸包里的东西我一直没看。</p><p>陈树那句话我后来拿本子拄了一下。</p><p>我写：他讲我存的都是不能讲的事。他说对了。</p><p>我写：可是我今天手上拿着这个纸包，我拿的不是不能讲。我拿的是今天已经讲了、但只能跟一个不在屋里的的人讲的那一部分。</p>',88)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
